mapper.update:
UPDATE exam_record
SET total_score = #{totalScore},
    submit_time = #{submitTime},
    status = #{status}
WHERE id = #{id}

mapper.select:
SELECT * FROM exam_record
WHERE user_id = #{userId}
ORDER BY id DESC
    LIMIT #{offset}, #{size}

SELECT * FROM exam_record
WHERE paper_id = #{paperId} AND user_id = #{userId}
ORDER BY id DESC LIMIT 1

SELECT * FROM exam_record
WHERE user_id = #{userId} AND status = #{status}
ORDER BY id DESC
